#include <iostream>
#include <unordered_map>
using namespace std;

int calc(int n, int m) {
    if (n < m) {
        swap(n, m);
    }
    if (m == 1) {
        static unordered_map<int, int> lookup_table = {{0, 0}, {1, 1}, {2, 2}, {3, 3}, {4, 2}, {5, 1}};
        return lookup_table[n % 6];
    }
    if (n == 7) {
        if (m == 2) {
            return 2;
        }
        return (n * m) % 2;
    } else if (n >= 4) {
        return (n * m) % 2;
    } else {
        static unordered_map<pair<int, int>, int, hash_pair> dict_pairs = {
            {{3, 2}, 2},
            {{3, 1}, 3},
            {{2, 2}, 4},
            {{2, 1}, 2}
        };
        auto it = dict_pairs.find({n, m});
        if (it != dict_pairs.end()) {
            return it->second;
        } else {
            return (n * m) % 2;
        }
    }
}

int main() {
    int num1, num2;
    cin >> num1 >> num2;
    cout << num1 * num2 - calc(num1, num2) << endl;
    return 0;
}

struct hash_pair {
    size_t operator()(const pair<int, int>& p) const {
        auto hash1 = hash<int>{}(p.first);
        auto hash2 = hash<int>{}(p.second);
        return hash1 ^ (hash2 << 1);
    }
};

